#!/usr/bin/env node
// Generates Rust and Kotlin types for the Preku bridge protocol from protocol/schemas/*.schema.json.
//
//   node protocol/codegen/generate.mjs           write generated files
//   node protocol/codegen/generate.mjs --check   fail if generated files are out of date (CI)
//
// Supports the JSON Schema subset we use: top-level objects with properties of type
// string | integer | number | boolean | object | array, plus $ref to another schema file.
// A schema with "x-type" is a message body; its type string becomes a constant.
// No dependencies on purpose (Rules.md §1).

import { readFileSync, readdirSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const schemaDir = join(root, "protocol/schemas");
const outputs = {
  rust: join(root, "desktop/src-tauri/src/protocol/generated.rs"),
  kotlin: join(root, "android/app/src/main/java/app/preku/bridge/protocol/Generated.kt"),
};
const HEADER = "@generated by protocol/codegen/generate.mjs from protocol/schemas. Do not edit.";
const RUST_KEYWORDS = new Set(["type", "ref", "match", "move", "self", "struct", "use", "where"]);

const version = Number(readFileSync(join(root, "protocol/VERSION"), "utf8").trim());
if (!Number.isInteger(version) || version < 1) throw new Error("protocol/VERSION must be an integer >= 1");

const schemas = readdirSync(schemaDir)
  .filter((f) => f.endsWith(".schema.json"))
  .sort()
  .map((file) => ({ file, schema: JSON.parse(readFileSync(join(schemaDir, file), "utf8")) }));

const titleByFile = new Map(schemas.map(({ file, schema }) => [file, schema.title]));

function refTitle(ref) {
  const title = titleByFile.get(ref);
  if (!title) throw new Error(`Unknown $ref ${ref}`);
  return title;
}

function snake(name) {
  return name.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase();
}

function rustType(prop, ctx) {
  if (prop.$ref) return refTitle(prop.$ref);
  switch (prop.type) {
    case "string":
      return "String";
    case "boolean":
      return "bool";
    case "number":
      return "f64";
    case "integer":
      return prop.format === "uint32" ? "u32" : "i64";
    case "array":
      return `Vec<${rustType(prop.items, ctx)}>`;
    case "object":
      return "serde_json::Map<String, serde_json::Value>";
    default:
      throw new Error(`${ctx}: unsupported type ${JSON.stringify(prop.type)}`);
  }
}

function kotlinType(prop, ctx) {
  if (prop.$ref) return refTitle(prop.$ref);
  switch (prop.type) {
    case "string":
      return "String";
    case "boolean":
      return "Boolean";
    case "number":
      return "Double";
    case "integer":
      return prop.format === "uint32" ? "Int" : "Long";
    case "array":
      return `List<${kotlinType(prop.items, ctx)}>`;
    case "object":
      return "JsonObject";
    default:
      throw new Error(`${ctx}: unsupported type ${JSON.stringify(prop.type)}`);
  }
}

function fields(schema) {
  const required = new Set(schema.required ?? []);
  return Object.entries(schema.properties ?? {}).map(([name, prop]) => ({
    name,
    prop,
    optional: !required.has(name),
  }));
}

function generateRust() {
  const out = [`// ${HEADER}`, "", "use serde::{Deserialize, Serialize};", ""];
  out.push(`pub const PROTOCOL_VERSION: u32 = ${version};`);
  const typed = schemas.filter(({ schema }) => schema["x-type"]);
  out.push("");
  out.push("/// Message `type` strings, one per body schema.");
  out.push("pub mod message_type {");
  for (const { schema } of typed) {
    out.push(`    pub const ${snake(schema.title).toUpperCase()}: &str = "${schema["x-type"]}";`);
  }
  out.push("}");
  for (const { file, schema } of schemas) {
    out.push("");
    if (schema.description) out.push(`/// ${schema.description}`);
    out.push("#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]");
    out.push('#[serde(rename_all = "camelCase")]');
    // An empty struct is written as rustfmt writes it (`Unpair {}`), so the check passes on
    // formatted code.
    if (fields(schema).length === 0) {
      out.push(`pub struct ${schema.title} {}`);
      continue;
    }
    out.push(`pub struct ${schema.title} {`);
    for (const { name, prop, optional } of fields(schema)) {
      const snakeName = snake(name);
      const ident = RUST_KEYWORDS.has(snakeName) ? `r#${snakeName}` : snakeName;
      let type = rustType(prop, `${file}#${name}`);
      if (prop.description) out.push(`    /// ${prop.description}`);
      if (optional) {
        out.push('    #[serde(default, skip_serializing_if = "Option::is_none")]');
        type = `Option<${type}>`;
      }
      out.push(`    pub ${ident}: ${type},`);
    }
    out.push("}");
  }
  return out.join("\n") + "\n";
}

function generateKotlin() {
  const body = [];
  let needsJsonObject = false;
  for (const { file, schema } of schemas) {
    body.push("");
    if (schema.description) body.push(`/** ${schema.description} */`);
    body.push("@Serializable");
    if (fields(schema).length === 0) {
      // Kotlin data classes need a field; an empty body is a plain class.
      body.push(`class ${schema.title}`);
      continue;
    }
    body.push(`data class ${schema.title}(`);
    for (const { name, prop, optional } of fields(schema)) {
      let type = kotlinType(prop, `${file}#${name}`);
      if (type.includes("JsonObject")) needsJsonObject = true;
      if (prop.description) body.push(`    /** ${prop.description} */`);
      body.push(`    val ${name}: ${type}${optional ? "? = null" : ""},`);
    }
    body.push(")");
  }
  const imports = ["import kotlinx.serialization.Serializable"];
  if (needsJsonObject) imports.push("import kotlinx.serialization.json.JsonObject");
  return (
    [
      `// ${HEADER}`,
      "package app.preku.bridge.protocol",
      "",
      ...imports,
      "",
      `const val PROTOCOL_VERSION: Int = ${version}`,
      "",
      "/** Message `type` strings, one per body schema. */",
      "object MessageType {",
      ...schemas
        .filter(({ schema }) => schema["x-type"])
        .map(({ schema }) => `    const val ${snake(schema.title).toUpperCase()} = "${schema["x-type"]}"`),
      "}",
      ...body,
    ].join("\n") + "\n"
  );
}

const generated = { rust: generateRust(), kotlin: generateKotlin() };
const check = process.argv.includes("--check");
let stale = false;

for (const [lang, path] of Object.entries(outputs)) {
  const current = existsSync(path) ? readFileSync(path, "utf8").replace(/\r\n/g, "\n") : null;
  if (current === generated[lang]) continue;
  if (check) {
    console.error(`✗ ${path} is out of date — run: node protocol/codegen/generate.mjs`);
    stale = true;
  } else {
    writeFileSync(path, generated[lang]);
    console.log(`✓ wrote ${path}`);
  }
}

if (stale) process.exit(1);
if (check) console.log("✓ generated protocol files are up to date");
